    const atL = (L) => { const c = base.cum; let i = 1; while (i < c.length - 1 && c[i] < L) i++; const u = (L - c[i - 1]) / ((c[i] - c[i - 1]) || 1); return [lerp(base.P[i - 1][0], base.P[i][0], u), lerp(base.P[i - 1][1], base.P[i][1], u)]; };
    for (let s = 0; s < base.len - 4; s += dash + gap) { const e = Math.min(base.len, s + dash), q = []; for (let u = s; u <= e; u += 5) q.push(atL(u)); q.push(atL(e)); out.push(mk(q, { jit: 0.3, kind: 'dash', ...o })); }
