        if (p.length === 2 && Math.hypot(p[1][0] - p[0][0], p[1][1] - p[0][1]) < 2) p[1] = [p[0][0] + 1.5, p[0][1] + 1.5];
        out.push(mk(WP(p), { w: o.w ?? Math.max(6, h * 0.12), col: o.col, jit: 0.3, wav: 90, kind: 'text' }));
