    for (const [u, v] of [[-0.55, -0.15], [0.1, -0.25], [0.55, 0.12], [-0.15, 0.25]]) out.push(curve(X([[u - 0.07, v], [u, v - 0.04], [u + 0.07, v]]), { ...c, w: c.w * 0.8 }), dot(...X([[u, v + 0.05]])[0], { w: c.w * 1.2, col: c.col }));
