    const ic = XC.ink.getContext('2d'); ic.setTransform(1, 0, 0, 1, 0, 0); ic.globalCompositeOperation = 'source-over'; ic.globalAlpha = 1; ic.clearRect(0, 0, W, H_);
    ic.save(); apply(ic); ic.lineCap = 'round'; ic.lineJoin = 'round';
    for (const s of S) {
      if (t <= s.a) continue; if (s.box[2] < vx0 || s.box[0] > vx1 || s.box[3] < vy0 || s.box[1] > vy1) continue;
      drawStroke(ic, s, s.len * prog(s, t), INK[s.col] || s.col, s.alpha);
    }
    ic.globalAlpha = 1; ic.globalCompositeOperation = 'destination-out'; const np = ic.createPattern(XC.nt, 'repeat'); ic.fillStyle = np; ic.globalAlpha = 0.85; ic.fillRect(vx0, vy0, vx1 - vx0, vy1 - vy0);
    ic.restore();
    ctx.save(); ctx.globalCompositeOperation = 'multiply'; ctx.globalAlpha = 0.94; ctx.drawImage(XC.ink, 0, 0); ctx.restore();
    // glossy sheen drifting at 0.35x the camera
    { const sx = -cx * z * 0.35 + 900, sy = -cy * z * 0.12; ctx.save(); const sh = ctx.createLinearGradient(sx - 700, sy, sx + 300, sy + 1500);
      sh.addColorStop(0, 'rgba(255,255,255,0)'); sh.addColorStop(0.42, 'rgba(255,255,255,0.10)'); sh.addColorStop(0.5, 'rgba(255,255,255,0.17)'); sh.addColorStop(0.58, 'rgba(255,255,255,0.10)'); sh.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = sh; ctx.fillRect(0, 0, W, H_); ctx.restore(); }
    // floating markers
