    squeak(0.4, 0.22); squeak(T(6, 'density'), 0.25); squeak(T(15, 'heavier'), 0.2); squeak(T(19, 'impossible'), 0.22);
    k.play('stamp', T(0, 'twentyfive'), { gain: 0.4 });
    k.play('pop', T(2, 'floats'), { f: 620, gain: 0.3 });
    k.play('thud', T(2, 'sinks'), { f: 100, gain: 0.35 });
    k.play('swish', T(3, 'water'), { gain: 0.3 });
    k.play('pop', T(4, 'bobs'), { f: 700, gain: 0.3 });
    k.play('thud', T(5, 'bottom'), { f: 90, gain: 0.4 });
    k.play('ding', T(6, 'density'), { f: 'E6', gain: 0.22 });
    k.play('success', T(7, 'floats'), { f: 'C6', gain: 0.25 });
    k.play('sparkle', T(9, 'air'), { n: 5, gain: 0.3 });
    k.play('ding', T(10, 'quarter'), { f: 'G5', gain: 0.22 });
    k.play('stamp', T(15, 'heavier'), { gain: 0.35 });
    k.play('thud', T(17, 'goes') + 0.3, { f: 80, gain: 0.45 });
    k.play('success', T(18, 'works'), { f: 'C6', gain: 0.25 });
